import io
from rich.file_proxy import FileProxy
from rich.console import Console

class MockFile(io.TextIOBase):
    def isatty(self):
        return True
    def write(self, s):
        pass
    def fileno(self):
        return 1

console = Console(file=io.StringIO())
proxy = FileProxy(console, MockFile())

print(f"MockFile isatty: {MockFile().isatty()}")
try:
    print(f"FileProxy isatty: {proxy.isatty()}")
except Exception as e:
    print(f"FileProxy isatty failed: {e}")

# Simulate rich.console._is_atty (simplified)
def check_isatty(file):
    isatty = getattr(file, "isatty", None)
    if isatty:
        return isatty()
    return False

print(f"Check isatty (MockFile): {check_isatty(MockFile())}")
print(f"Check isatty (FileProxy): {check_isatty(proxy)}")

